"use client";

import { ChevronDown, LockClosed } from "@nebutra/icons";
import {
  createContext,
  type HTMLAttributes,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  use,
} from "react";
import { overlayClassNames } from "../tokens/components/overlay";
import { cn } from "../utils/cn";
import { Button, type ButtonProps } from "./button";
import {
  DropdownMenu,
  DropdownMenuContent,
  type DropdownMenuContentProps,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "./dropdown-menu";

/* -------------------------------------------------------------------------- *\
 *  Menu family — Geist-flat API on top of DropdownMenu.
 *
 *  Use cases (per Geist guidance):
 *    Discoverable trigger that opens a list of actions on a single resource
 *    (a dots menu on a row, a dropdown on a primary entity). For right-click
 *    or long-press on a row use ContextMenu; for ⌘K global commands use
 *    CommandMenu; for two related primary actions use a split button.
 *
 *  Behavior — inherited from Base UI / DropdownMenu:
 *    Open on click (not hover), Arrow/Home/End/Enter/Space navigation,
 *    typeahead, close on item activation / Escape / outside-click, focus
 *    returns to trigger on close, position auto-flips on window bounds.
 *
 *  Why this lives next to DropdownMenu, not as a fork:
 *    DropdownMenu encodes all the heavy a11y wiring. Menu* is a thin facade
 *    that rewrites Geist's surface (title-cased section headers, lock icon
 *    on permission-gated rows, prefix/suffix slots, error coloring) into
 *    DropdownMenu primitives. Don't duplicate behavior.
\* -------------------------------------------------------------------------- */

// ---------------------------------------------------------------------------
// Position → side/align mapping
// ---------------------------------------------------------------------------

export type MenuPosition =
  | "bottom-start"
  | "bottom-end"
  | "top-start"
  | "top-end"
  | "right-start"
  | "right-end"
  | "left-start"
  | "left-end";

type Side = "top" | "right" | "bottom" | "left";
type Align = "start" | "end";

function splitPosition(position: MenuPosition): { side: Side; align: Align } {
  const [side, align] = position.split("-") as [Side, Align];
  return { side, align };
}

// ---------------------------------------------------------------------------
// Context — share position from MenuContainer down to Menu
// ---------------------------------------------------------------------------

const MenuContext = createContext<MenuPosition | null>(null);

function useMenuPosition(): MenuPosition {
  return use(MenuContext) ?? "bottom-start";
}

// ---------------------------------------------------------------------------
// MenuContainer
// ---------------------------------------------------------------------------

export interface MenuContainerProps {
  /** Anchor + alignment of the popup. @default "bottom-start" */
  position?: MenuPosition;
  children: ReactNode;
}

export function MenuContainer({ position = "bottom-start", children }: MenuContainerProps) {
  return (
    <MenuContext.Provider value={position}>
      <DropdownMenu>{children}</DropdownMenu>
    </MenuContext.Provider>
  );
}

// ---------------------------------------------------------------------------
// MenuButton
// ---------------------------------------------------------------------------

export interface MenuButtonProps extends Omit<ButtonProps, "variant" | "size" | "shape" | "type"> {
  /** Append a chevron-down glyph after the label. */
  showChevron?: boolean;
  /** Geist Button "type" alias. */
  type?: "primary" | "secondary" | "tertiary" | "ghost" | "warning" | "destructive";
  /** "unstyled" strips chrome so an arbitrary trigger (avatar, dots) takes over. */
  variant?: "unstyled";
  /** Geist sizes. */
  size?: "small" | "medium" | "large" | "tiny";
  shape?: "default" | "square" | "circle";
  /** Trigger contains only an SVG; ensure an aria-label is set. */
  svgOnly?: boolean;
}

const GEIST_TYPE_TO_VARIANT = {
  primary: "default",
  secondary: "secondary",
  tertiary: "tertiary",
  ghost: "ghost",
  warning: "warning",
  destructive: "destructive",
} as const;

const GEIST_SIZE_TO_NEBUTRA = {
  tiny: "tiny",
  small: "sm",
  medium: "default",
  large: "lg",
} as const;

export const MenuButton = function MenuButton({
  showChevron,
  type = "primary",
  variant,
  size = "medium",
  shape = "default",
  svgOnly,
  children,
  className,
  onClick,
  prefix,
  suffix,
  loading,
  "aria-label": ariaLabel,
  ref,
  ...rest
}: MenuButtonProps & { ref?: Ref<HTMLButtonElement> | undefined }) {
  const isUnstyled = variant === "unstyled";

  // For the bare-button path, narrow to just the HTML attributes we know are
  // safe; ButtonProps's polymorphic shape doesn't compose with <button> here.
  const buttonHtmlProps = {
    ...(onClick !== undefined ? { onClick } : {}),
    ...(ariaLabel !== undefined ? { "aria-label": ariaLabel } : {}),
  };

  return (
    <DropdownMenuTrigger asChild>
      {isUnstyled ? (
        // "unstyled" — render a bare button so callers can wrap an avatar,
        // dots icon, etc. without inheriting Button chrome.
        <button
          ref={ref}
          type="button"
          className={cn(
            "inline-flex items-center justify-center rounded-[var(--radius-md)]",
            overlayClassNames.focusRing,
            className,
          )}
          {...buttonHtmlProps}
        >
          {children}
        </button>
      ) : (
        <Button
          ref={ref}
          variant={GEIST_TYPE_TO_VARIANT[type]}
          size={GEIST_SIZE_TO_NEBUTRA[size]}
          shape={shape}
          className={className}
          {...(loading !== undefined ? { loading } : {})}
          {...(prefix !== undefined ? { prefix } : {})}
          {...(suffix !== undefined ? { suffix } : {})}
          {...(ariaLabel !== undefined ? { "aria-label": ariaLabel } : {})}
          {...rest}
        >
          {svgOnly ? (
            children
          ) : (
            <>
              {children}
              {showChevron && <ChevronDown className="h-3.5 w-3.5 opacity-70" />}
            </>
          )}
        </Button>
      )}
    </DropdownMenuTrigger>
  );
};

// ---------------------------------------------------------------------------
// Menu (the popup)
// ---------------------------------------------------------------------------

export interface MenuProps extends Omit<DropdownMenuContentProps, "side" | "align"> {
  /** Fixed pixel width for the popup; otherwise it sizes to content. */
  width?: number | string;
}

export const Menu = function Menu({
  width,
  style,
  className,
  children,
  ref,
  ...rest
}: MenuProps & { ref?: Ref<HTMLDivElement> | undefined }) {
  const { side, align } = splitPosition(useMenuPosition());
  const widthStyle = width !== undefined ? { width } : {};
  return (
    <DropdownMenuContent
      ref={ref}
      side={side}
      align={align}
      style={{ ...widthStyle, ...style }}
      className={cn("min-w-32", className)}
      {...rest}
    >
      {children}
    </DropdownMenuContent>
  );
};

// ---------------------------------------------------------------------------
// MenuItem
// ---------------------------------------------------------------------------

type MenuItemKind = "default" | "error";

export interface MenuItemProps {
  onClick?: () => void;
  /** Render as an anchor; mutually exclusive with onClick semantically. */
  href?: string;
  disabled?: boolean;
  prefix?: ReactNode;
  suffix?: ReactNode;
  /** `error` renders the row in destructive red — for delete actions. */
  type?: MenuItemKind;
  /**
   * When `href` is present and you need framework-specific routing
   * (next/link, react-router), pass `as={Link}` instead of `<a>`.
   */
  as?: "a" | (() => ReactElement);
  className?: string;
  children: ReactNode;
}

function getTextFromNode(node: ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) {
    const parts: string[] = [];
    for (const child of node) {
      const text = getTextFromNode(child);
      if (text) parts.push(text);
    }
    return parts.join(" ");
  }
  if (isValidElement<{ children?: ReactNode }>(node)) return getTextFromNode(node.props.children);
  return "";
}

export const MenuItem = function MenuItem({
  ref,
  onClick,
  href,
  disabled,
  prefix,
  suffix,
  type = "default",
  className,
  children,
}: MenuItemProps & { ref?: Ref<HTMLDivElement> | undefined }) {
  const content = (
    <span className="flex flex-1 items-center gap-2">
      {prefix && (
        <span aria-hidden="true" className="inline-flex shrink-0 [&_svg]:size-4">
          {prefix}
        </span>
      )}
      <span className="flex-1 truncate">{children}</span>
      {suffix && (
        <span aria-hidden="true" className="inline-flex shrink-0 [&_svg]:size-4">
          {suffix}
        </span>
      )}
    </span>
  );

  const errorClass =
    type === "error"
      ? "text-destructive data-[highlighted]:bg-destructive/10 data-[highlighted]:text-destructive"
      : "";

  // exactOptionalPropertyTypes: only forward props that are defined.
  const passthrough: { onClick?: () => void; disabled?: boolean } = {};
  if (onClick !== undefined) passthrough.onClick = onClick;
  if (disabled !== undefined) passthrough.disabled = disabled;

  if (href !== undefined) {
    const anchorLabel = getTextFromNode(children);

    return (
      <DropdownMenuItem
        ref={ref}
        // Render the item as an anchor so middle-click + right-click both work.
        // Base UI's `render` pattern slots `content` in as the anchor's child
        // at render time, so the `<a>` is not actually empty at runtime.
        // biome-ignore lint/a11y/useAnchorContent: content is injected by Base UI's render-prop pattern at mount time.
        render={<a href={href} aria-label={anchorLabel || undefined} />}
        className={cn(errorClass, className)}
        {...passthrough}
      >
        {content}
      </DropdownMenuItem>
    );
  }

  return (
    <DropdownMenuItem ref={ref} className={cn(errorClass, className)} {...passthrough}>
      {content}
    </DropdownMenuItem>
  );
};

// ---------------------------------------------------------------------------
// MenuLink — shortcut for href-only items
// ---------------------------------------------------------------------------

export interface MenuLinkProps extends Omit<MenuItemProps, "onClick" | "href"> {
  href: string;
}

export const MenuLink = function MenuLink({
  ref,
  ...props
}: MenuLinkProps & { ref?: Ref<HTMLDivElement> | undefined }) {
  return <MenuItem ref={ref} {...props} />;
};

// ---------------------------------------------------------------------------
// MenuItemLocked — permission-gated; visually disabled + lock icon suffix
// ---------------------------------------------------------------------------

export interface MenuItemLockedProps extends Omit<MenuItemProps, "disabled" | "type" | "suffix"> {
  /** Wire an onClick anyway — useful for analytics on attempted activation. */
  onClick?: () => void;
}

export const MenuItemLocked = function MenuItemLocked({
  children,
  ref,
  ...rest
}: MenuItemLockedProps & { ref?: Ref<HTMLDivElement> | undefined }) {
  return (
    <MenuItem ref={ref} disabled suffix={<LockClosed aria-hidden="true" />} {...rest}>
      {children}
    </MenuItem>
  );
};

// ---------------------------------------------------------------------------
// MenuSection — labeled group of items
// ---------------------------------------------------------------------------

export interface MenuSectionProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "children" | "title"> {
  /** Title Case, 1–2 words (Workspace, Recent Projects). */
  title?: ReactNode;
  /** Render a divider above the section. @default true after the first */
  showDivider?: boolean;
  children: ReactNode;
}

export const MenuSection = function MenuSection({
  title,
  showDivider,
  children,
  className,
  ref,
  ...rest
}: MenuSectionProps & { ref?: Ref<HTMLDivElement> | undefined }) {
  return (
    <>
      {showDivider && <DropdownMenuSeparator />}
      <DropdownMenuGroup ref={ref} className={className} {...rest}>
        {title && (
          <DropdownMenuLabel className="text-muted-foreground text-xs uppercase tracking-wide">
            {title}
          </DropdownMenuLabel>
        )}
        {children}
      </DropdownMenuGroup>
    </>
  );
};

"use client";

import type { VariantProps } from "class-variance-authority";
import type * as React from "react";
import { cn } from "../utils/cn";
import { Slot } from "../utils/slot";
import { buttonVariants } from "./button-variants";

// ─── Spinner ──────────────────────────────────────────────────────────────────
// Uses @keyframes spinner from globals.css

function Spinner({ className }: { className?: string }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "block rounded-full border-2 border-current border-t-transparent animate-[spinner_0.6s_linear_infinite]",
        className,
      )}
    />
  );
}

// ─── Icon size class mapping ──────────────────────────────────────────────────

function getIconSizeClass(size: string | null | undefined): string {
  switch (size) {
    case "tiny":
      return "[&>svg]:size-3"; // 12px
    case "sm":
      return "[&>svg]:size-3.5"; // 14px
    case "lg":
      return "[&>svg]:size-4.5"; // 18px
    default:
      return "[&>svg]:size-4"; // 16px
  }
}

function getSpinnerSizeClass(size: string | null | undefined): string {
  switch (size) {
    case "tiny":
      return "size-3"; // 12px
    case "sm":
      return "size-3.5"; // 14px
    case "lg":
      return "size-4.5"; // 18px
    default:
      return "size-4"; // 16px
  }
}

// ─── Shadow class mapping ─────────────────────────────────────────────────────

const SHADOW_CLASSES: Record<string, string> = {
  sm: "shadow-sm",
  md: "shadow-md",
  lg: "shadow-md",
};

function resolveShadowClass(shadow: boolean | "sm" | "md" | "lg" | undefined): string | undefined {
  if (!shadow) return undefined;
  const level = shadow === true ? "md" : shadow;
  return SHADOW_CLASSES[level];
}

// ─── ButtonContent (shared between Button & ButtonLink) ───────────────────────

interface ButtonContentProps {
  loading: boolean;
  prefix?: React.ReactNode | undefined;
  suffix?: React.ReactNode | undefined;
  size?: string | null | undefined;
  children?: React.ReactNode | undefined;
}

function ButtonContent({ loading, prefix, suffix, size, children }: ButtonContentProps) {
  const iconSizeClass = getIconSizeClass(size);

  return (
    <>
      {loading && <Spinner className={getSpinnerSizeClass(size)} />}
      {prefix != null && (
        <span aria-hidden="true" className={cn("shrink-0", iconSizeClass)}>
          {prefix}
        </span>
      )}
      {children}
      {suffix != null && (
        <span aria-hidden="true" className={cn("shrink-0", iconSizeClass)}>
          {suffix}
        </span>
      )}
    </>
  );
}

// ─── Button ───────────────────────────────────────────────────────────────────

export interface ButtonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "prefix">,
    VariantProps<typeof buttonVariants> {
  /** Render as a child element (Radix Slot — polymorphic) */
  asChild?: boolean;
  /** Show loading spinner and disable interaction */
  loading?: boolean;
  /** Icon or element rendered before children */
  prefix?: React.ReactNode;
  /** Icon or element rendered after children */
  suffix?: React.ReactNode;
  /** Elevation shadow level. `true` resolves to `"md"` */
  shadow?: boolean | "sm" | "md" | "lg";
}

const Button = ({
  className,
  variant,
  size,
  shape,
  asChild = false,
  loading = false,
  disabled,
  prefix,
  suffix,
  shadow,
  children,
  ref,
  ...props
}: ButtonProps & { ref?: React.Ref<HTMLButtonElement> | undefined }) => {
  const Comp = asChild ? Slot : "button";
  const isDisabled = Boolean(disabled || loading);
  const shadowClass = resolveShadowClass(shadow);

  return (
    <Comp
      ref={ref}
      className={cn(buttonVariants({ variant, size, shape }), shadowClass, className)}
      disabled={isDisabled}
      aria-busy={loading || undefined}
      {...props}
    >
      {asChild ? (
        children
      ) : (
        <ButtonContent loading={loading} prefix={prefix} suffix={suffix} size={size}>
          {children}
        </ButtonContent>
      )}
    </Comp>
  );
};
Button.displayName = "Button";

// ─── ButtonLink ───────────────────────────────────────────────────────────────

export interface ButtonLinkProps
  extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "prefix">,
    VariantProps<typeof buttonVariants> {
  /** Icon or element rendered before children */
  prefix?: React.ReactNode;
  /** Icon or element rendered after children */
  suffix?: React.ReactNode;
  /** Elevation shadow level. `true` resolves to `"md"` */
  shadow?: boolean | "sm" | "md" | "lg";
  /** Show loading spinner */
  loading?: boolean;
}

const ButtonLink = ({
  className,
  variant,
  size,
  shape,
  prefix,
  suffix,
  shadow,
  loading = false,
  children,
  ref,
  ...props
}: ButtonLinkProps & { ref?: React.Ref<HTMLAnchorElement> | undefined }) => {
  const shadowClass = resolveShadowClass(shadow);

  const loadingProps = loading
    ? {
        "aria-busy": "true" as const,
        "aria-disabled": "true" as const,
        tabIndex: -1,
      }
    : {};

  return (
    <a
      ref={ref}
      className={cn(
        buttonVariants({ variant, size, shape }),
        shadowClass,
        loading && "pointer-events-none opacity-50",
        className,
      )}
      {...loadingProps}
      {...props}
    >
      <ButtonContent loading={loading} prefix={prefix} suffix={suffix} size={size}>
        {children}
      </ButtonContent>
    </a>
  );
};
ButtonLink.displayName = "ButtonLink";

export { Button, ButtonLink };

"use client";

import { Menu as BaseMenu } from "@base-ui/react/menu";
import { Check, ChevronRight, Status as Circle } from "@nebutra/icons";
import * as React from "react";
import { overlayClassNames, overlayZIndex } from "../tokens/components/overlay";
import { cn } from "../utils/cn";
import { overlayPrimitiveClassNames } from "./overlay";

type DropdownMenuContextValue = {
  setOpen: (open: boolean) => void;
};

const DropdownMenuContext = React.createContext<DropdownMenuContextValue | null>(null);

type DropdownMenuProps = React.ComponentPropsWithoutRef<typeof BaseMenu.Root>;

function DropdownMenu({
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
  children,
  ...props
}: DropdownMenuProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
  const open = controlledOpen ?? uncontrolledOpen;

  function setOpen(
    nextOpen: boolean,
    eventDetails?: Parameters<NonNullable<DropdownMenuProps["onOpenChange"]>>[1],
  ) {
    if (controlledOpen === undefined) {
      setUncontrolledOpen(nextOpen);
    }
    onOpenChange?.(nextOpen, eventDetails as never);
  }

  const contextValue: DropdownMenuContextValue = { setOpen };

  return (
    <DropdownMenuContext.Provider value={contextValue}>
      <BaseMenu.Root open={open} onOpenChange={setOpen} {...props}>
        {children}
      </BaseMenu.Root>
    </DropdownMenuContext.Provider>
  );
}
DropdownMenu.displayName = "DropdownMenu";

type DropdownMenuTriggerProps = React.ComponentProps<typeof BaseMenu.Trigger> & {
  asChild?: boolean;
};

const DropdownMenuTrigger = ({
  asChild,
  children,
  render,
  ref,
  ...props
}: DropdownMenuTriggerProps & { ref?: React.Ref<HTMLButtonElement> | undefined }) => {
  const context = React.use(DropdownMenuContext);
  function openFromTrigger() {
    context?.setOpen(true);
  }

  const childRenderElement =
    asChild && React.isValidElement<Record<string, unknown>>(children)
      ? React.cloneElement(children, {
          onMouseDown: (event: React.MouseEvent<HTMLElement>) => {
            (
              children.props.onMouseDown as
                | ((event: React.MouseEvent<HTMLElement>) => void)
                | undefined
            )?.(event);
            if (!event.defaultPrevented) {
              openFromTrigger();
            }
          },
          onKeyDown: (event: React.KeyboardEvent<HTMLElement>) => {
            (
              children.props.onKeyDown as
                | ((event: React.KeyboardEvent<HTMLElement>) => void)
                | undefined
            )?.(event);
            if (!event.defaultPrevented && (event.key === "Enter" || event.key === " ")) {
              openFromTrigger();
            }
          },
        })
      : null;

  const renderElement = childRenderElement ?? render;
  return (
    <BaseMenu.Trigger
      ref={ref}
      render={renderElement as React.ComponentProps<typeof BaseMenu.Trigger>["render"]}
      {...(renderElement ? props : { ...props, children })}
    />
  );
};
DropdownMenuTrigger.displayName = "DropdownMenuTrigger";

const DropdownMenuGroup = BaseMenu.Group;

const DropdownMenuPortal = BaseMenu.Portal;

const DropdownMenuSub = BaseMenu.SubmenuRoot;

const DropdownMenuRadioGroup = BaseMenu.RadioGroup;

const DropdownMenuSubTrigger = ({
  className,
  inset,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseMenu.SubmenuTrigger> & {
  inset?: boolean;
} & { ref?: React.Ref<React.ElementRef<typeof BaseMenu.SubmenuTrigger>> | undefined }) => (
  <BaseMenu.SubmenuTrigger
    ref={ref}
    className={cn(overlayPrimitiveClassNames.menuSubTrigger, inset && "pl-8", className)}
    {...props}
  >
    {children}
    <ChevronRight className="ml-auto size-4" />
  </BaseMenu.SubmenuTrigger>
);
DropdownMenuSubTrigger.displayName = "DropdownMenuSubTrigger";

const DropdownMenuSubContent = ({
  className,
  style,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseMenu.Popup> & {
  ref?: React.Ref<React.ElementRef<typeof BaseMenu.Popup>> | undefined;
}) => (
  <BaseMenu.Portal>
    <BaseMenu.Positioner>
      <BaseMenu.Popup
        ref={ref}
        className={cn(
          overlayClassNames.menuSurface,
          overlayPrimitiveClassNames.menuSurface,
          className,
        )}
        style={{ zIndex: overlayZIndex.popover, ...style }}
        {...props}
      />
    </BaseMenu.Positioner>
  </BaseMenu.Portal>
);
DropdownMenuSubContent.displayName = "DropdownMenuSubContent";

export interface DropdownMenuContentProps
  extends React.ComponentPropsWithoutRef<typeof BaseMenu.Popup> {
  align?: React.ComponentProps<typeof BaseMenu.Positioner>["align"];
  sideOffset?: React.ComponentProps<typeof BaseMenu.Positioner>["sideOffset"];
  alignOffset?: React.ComponentProps<typeof BaseMenu.Positioner>["alignOffset"];
  side?: React.ComponentProps<typeof BaseMenu.Positioner>["side"];
}

const DropdownMenuContent = ({
  className,
  style,
  sideOffset = 4,
  align = "center",
  alignOffset = 0,
  side = "bottom",
  ref,
  ...props
}: DropdownMenuContentProps & {
  ref?: React.Ref<React.ElementRef<typeof BaseMenu.Popup>> | undefined;
}) => (
  <BaseMenu.Portal>
    <BaseMenu.Positioner
      sideOffset={sideOffset}
      align={align}
      alignOffset={alignOffset}
      side={side}
    >
      <BaseMenu.Popup
        ref={ref}
        className={cn(
          overlayClassNames.menuSurface,
          overlayPrimitiveClassNames.menuSurface,
          className,
        )}
        style={{ zIndex: overlayZIndex.popover, ...style }}
        {...props}
      />
    </BaseMenu.Positioner>
  </BaseMenu.Portal>
);
DropdownMenuContent.displayName = "DropdownMenuContent";

const DropdownMenuItem = ({
  className,
  inset,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseMenu.Item> & {
  inset?: boolean;
} & { ref?: React.Ref<React.ElementRef<typeof BaseMenu.Item>> | undefined }) => (
  <BaseMenu.Item
    ref={ref}
    className={cn(overlayPrimitiveClassNames.menuItem, inset && "pl-8", className)}
    {...props}
  />
);
DropdownMenuItem.displayName = "DropdownMenuItem";

const DropdownMenuCheckboxItem = ({
  className,
  children,
  checked,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseMenu.CheckboxItem> & {
  ref?: React.Ref<React.ElementRef<typeof BaseMenu.CheckboxItem>> | undefined;
}) => (
  <BaseMenu.CheckboxItem
    ref={ref}
    className={cn(overlayPrimitiveClassNames.menuCheckboxItem, className)}
    {...(checked !== undefined && { checked })}
    {...props}
  >
    <span className="absolute left-2 flex size-3.5 items-center justify-center">
      <BaseMenu.CheckboxItemIndicator>
        <Check className="size-4" />
      </BaseMenu.CheckboxItemIndicator>
    </span>
    {children}
  </BaseMenu.CheckboxItem>
);
DropdownMenuCheckboxItem.displayName = "DropdownMenuCheckboxItem";

const DropdownMenuRadioItem = ({
  className,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseMenu.RadioItem> & {
  ref?: React.Ref<React.ElementRef<typeof BaseMenu.RadioItem>> | undefined;
}) => (
  <BaseMenu.RadioItem
    ref={ref}
    className={cn(overlayPrimitiveClassNames.menuCheckboxItem, className)}
    {...props}
  >
    <span className="absolute left-2 flex size-3.5 items-center justify-center">
      <BaseMenu.RadioItemIndicator>
        <Circle className="size-2 fill-current" />
      </BaseMenu.RadioItemIndicator>
    </span>
    {children}
  </BaseMenu.RadioItem>
);
DropdownMenuRadioItem.displayName = "DropdownMenuRadioItem";

const MENU_RESERVED_KEYS = new Set(["ArrowUp", "ArrowDown", "Enter", "Tab"]);

/**
 * Text filter for a long menu (language wheels, workspace lists).
 *
 * Menu popups own every printable keystroke: Base UI wires `useTypeahead` on the
 * popup and calls `preventDefault()` + `stopPropagation()` for any single
 * character key, so a bare `<input>` dropped into menu content cannot be typed
 * into at all. This primitive is the supported way to put one there — it stops
 * the keydown before the popup's typeahead and list-navigation handlers see it,
 * while deliberately letting ArrowUp / ArrowDown / Enter / Tab through so the
 * keyboard path from the filter into the filtered items still works. Escape is
 * unaffected either way: dismissal is bound on `document`, not on the popup.
 */
const DropdownMenuFilterInput = ({
  className,
  onKeyDown,
  ref,
  ...props
}: Omit<React.ComponentPropsWithoutRef<"input">, "type"> & {
  ref?: React.Ref<HTMLInputElement> | undefined;
}) => (
  <input
    ref={ref}
    type="search"
    className={cn(overlayPrimitiveClassNames.menuFilterInput, className)}
    onKeyDown={(event) => {
      onKeyDown?.(event);
      // Caret keys and printable characters belong to the field, not the menu.
      // Arrow up/down, Enter and Tab stay with the menu so the keyboard path
      // out of the filter and into the filtered items is preserved.
      if (!MENU_RESERVED_KEYS.has(event.key)) {
        event.stopPropagation();
      }
    }}
    {...props}
  />
);
DropdownMenuFilterInput.displayName = "DropdownMenuFilterInput";

/** Shown in place of items when a `DropdownMenuFilterInput` matches nothing. */
const DropdownMenuEmpty = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div
    role="presentation"
    className={cn(overlayPrimitiveClassNames.menuEmpty, className)}
    {...props}
  />
);
DropdownMenuEmpty.displayName = "DropdownMenuEmpty";

const DropdownMenuLabel = ({
  className,
  inset,
  ref,
  ...props
}: React.HTMLAttributes<HTMLDivElement> & {
  inset?: boolean;
} & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div
    ref={ref}
    className={cn("px-2 py-1.5 text-sm font-semibold", inset && "pl-8", className)}
    {...props}
  />
);
DropdownMenuLabel.displayName = "DropdownMenuLabel";

const DropdownMenuSeparator = ({
  className,
  orientation = "horizontal",
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseMenu.Separator> & {
  ref?: React.Ref<React.ElementRef<typeof BaseMenu.Separator>> | undefined;
}) => (
  <BaseMenu.Separator
    ref={ref}
    orientation={orientation}
    className={cn("-mx-1 my-1 h-px bg-muted", className)}
    {...props}
  />
);
DropdownMenuSeparator.displayName = "DropdownMenuSeparator";

const DropdownMenuShortcut = ({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) => {
  return (
    <span className={cn("ml-auto text-xs tracking-widest opacity-60", className)} {...props} />
  );
};
DropdownMenuShortcut.displayName = "DropdownMenuShortcut";

